async function visibleControl(page,selector){
 const control=page.locator(selector).first();await control.waitFor({state:'attached'});
 for(let attempt=0;attempt<6&&!await control.isVisible();attempt++){
  const inside=selector.replace(/^#panel\s+/,''),fold=page.locator('#panel details:not([open])').filter({has:page.locator(inside)}).first();
  if(!await fold.count())break;await fold.locator(':scope > summary').click();
 }
 await control.waitFor({state:'visible'});return control;
}

async function nativeNumber(page,name,value){
 const control=await visibleControl(page,'#panel input[type="number"][data-sl="'+name+'"]');
 await control.fill(String(value));await control.dispatchEvent('change');
}

